import path from 'node:path';
import { expect, test } from './fixtures';
import { collectErrors, uniqueCallsign } from './helpers';
import { ClaimPage } from './pages/claim';

test('debug: burst screenshots during flash window', async ({ browser, e2eServer }) => {
  const { baseURL } = e2eServer;
  test.setTimeout(150_000);
  const context = await browser.newContext();
  const page = await context.newPage();
  collectErrors(page);
  const claim = new ClaimPage(page, baseURL);
  await claim.claim(uniqueCallsign('dbg'));
  await expect(page.locator('#ship-hud-cargo')).toBeVisible({ timeout: 20_000 });
  await page.evaluate(() => {
    document.documentElement.dataset.fxSlow = '1';
  });
  await expect(page.locator('#weapon-hud')).toBeVisible({ timeout: 20_000 });
  const box = await page.locator('#game-canvas').boundingBox();
  if (!box) throw new Error('no box');
  const cx = box.x + box.width / 2;
  const cy = box.y + box.height / 2;
  await page.mouse.click(cx, cy);
  await page.waitForFunction(
    () => (window.__FX__?.laserFlashes ?? 0) >= 1,
    undefined,
    { timeout: 5_000, polling: 16 },
  );
  const fx = await page.evaluate(() => window.__FX__ as { events: unknown[] });
  console.log('FX state:', JSON.stringify(fx, null, 1).slice(0, 2000));
  for (let i = 0; i < 4; i++) {
    await page.screenshot({
      path: path.join(__dirname, `../../../.ralph/screenshots/dbg-fx-${i}.png`),
    });
    await page.waitForTimeout(120);
