import path from 'node:path';
import { expect, test } from './fixtures';
import { collectErrors, uniqueCallsign } from './helpers';
import { ClaimPage } from './pages/claim';

test('debug: continuous fire + burst screenshots', async ({ browser, e2eServer }) => {
  const { baseURL } = e2eServer;
  test.setTimeout(150_000);
  const context = await browser.newContext();
  const page = await context.newPage();
  collectErrors(page);
  const claim = new ClaimPage(page, baseURL);
  await claim.claim(uniqueCallsign('dbg'));
  await expect(page.locator('#ship-hud-cargo')).toBeVisible({ timeout: 20_000 });
  await page.evaluate(() => {
    document.documentElement.dataset.fxSlow = '1';
  });
  await expect(page.locator('#weapon-hud')).toBeVisible({ timeout: 20_000 });
  const box = await page.locator('#game-canvas').boundingBox();
  if (!box) throw new Error('no box');
  const cx = box.x + box.width / 2;
  const cy = box.y + box.height / 2;
  // Fire as fast as the 333 ms cooldown allows while capturing frames.
  const clicks = Promise.all(
    Array.from({ length: 12 }, (_, i) =>
      (async () => {
        await page.waitForTimeout(i * 340);
        await page.mouse.click(cx, cy);
      })(),
    ),
  );
  for (let i = 0; i < 10; i++) {
    await page.waitForTimeout(300);
    const n = await page.evaluate(() => window.__FX__?.laserFlashes ?? 0);
    await page.screenshot({
      path: path.join(__dirname, `../../../.ralph/screenshots/dbg-spam-${i}.png`),
    });
    console.log(`frame ${i}: laserFlashes=${n}`);
  }
  await clicks;
  console.log(
    'final fx:',
    JSON.stringify(await page.evaluate(() => window.__FX__)),
  );
  await context.close();
});

